import csv,json
with open('left.csv',newline='') as f: left=list(csv.DictReader(f))
with open('right.csv',newline='') as f: right=list(csv.DictReader(f))
first={}
for r in right: first.setdefault(r['id'],r['extra'])
print(json.dumps({'exit':0,'header':'id,name,extra','unmatched-empty':first.get(left[2]['id'],''),'duplicate-first':first[left[0]['id']]}))
